fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            let lines: Vec<String> = if keepends {
                // split_inclusive keeps the newline characters
                let split_iter = s.split_inclusive('\n');
                let collected: Vec<String> = split_iter.map(|line| line.to_string()).collect();
                // If input string does not contain '\n', split_inclusive yields one element (the whole string)
                // But if input string is empty, collected could be empty - check here:
                if collected.is_empty() {
                    vec![s]
                } else {
                    collected
                }
            } else {
                // lines() does not keep line endings
                let split_iter = s.lines();
                let collected: Vec<String> = split_iter.map(|line| line.to_string()).collect();
                if collected.is_empty() {
                    vec![s]
                } else {
                    collected
                }
            };
            lines
        })
        .collect()
}